-- 添加 Debugger 服务
return function(services: IServiceCollection, options: ITangSengDebuggerOptions)
	services:AddHostedService(script.Parent.TangSengDebugger, "ITangSengDebugger")

	options = options or {}
	if not options.KeyCode then
		options.KeyCode = Enum.KeyCode.F4
	end

	services:AddSingleton("ITangSengDebuggerOptions", options)

	services:AddSingleton("ITangSengDebugInfo", script.Parent.DebugInfo.TangSengDebugInfo)

	services:AddTangSengDebuggerPlugins(script.Parent.DebugInfo.DebuggerPlugins)
end
